import smbus,time
b=smbus.SMBus(1)
a=0x48
def r(c):
    d=b.read_i2c_block_data(a,c,2)
    return (d[0]<<8)|d[1]
def s(c):
    c|=0x8000
    b.write_i2c_block_data(a,1,[c>>8,c&0xff])
    while b.read_byte_data(a,1)&0x8000:time.sleep(0.001)
    return r(0)&0xfff
while 1:
    for i in range(4):
        s(i)
        print(i,r(i))
    time.sleep(0.05)

