import cv2
import time
import numpy as np

# Constants
MOTION_THRESHOLD = 10
CAPTURE_INTERVAL = 2  # seconds
WARM_UP_DELAY = 2  # seconds
OUTPUT_FILENAME = "motion.jpg"

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        time.sleep(WARM_UP_DELAY)
        return camera
    except IOError as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        ret, frame = camera.read()
        if not ret:
            raise IOError("Failed to capture frame")
        return frame
    except IOError as e:
        print(f"Error capturing frame: {e}")
        return None

def calculate_average_intensity(frame):
    """Calculates the average pixel intensity of a frame."""
    return np.mean(frame)

def detect_motion(baseline_intensity, current_intensity):
    """Detects motion based on the difference in average pixel intensity."""
    return abs(baseline_intensity - current_intensity) > MOTION_THRESHOLD

def save_image(frame, filename):
    """Saves the current frame to a file."""
    try:
        cv2.imwrite(filename, frame)
        print(f"Image saved: {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    """Main function to run the motion detection and image capture."""
    camera = initialize_camera()
    if camera is None:
        return

    baseline_intensity = calculate_average_intensity(capture_frame(camera))
    if baseline_intensity is None:
        camera.release()
        return

    try:
        while True:
            current_frame = capture_frame(camera)
            if current_frame is None:
                break

            current_intensity = calculate_average_intensity(current_frame)

            if detect_motion(baseline_intensity, current_intensity):
                print("Motion detected!")
                save_image(current_frame, OUTPUT_FILENAME)
                baseline_intensity = current_intensity  # Update baseline

            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Release resources
        camera.release()
        cv2.destroyAllWindows()
        print("Camera resources released.")

if __name__ == "__main__":
    main()

