        return None

def capture_frame(camera):
    """Captures a frame from the camera and returns it."""
    try:
        ret, frame = camera.read()
        if not ret:
            raise Exception("Failed to capture frame")
        return frame
    except Exception as e:
        log_error(f"Frame capture failed: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame and returns the decoded data."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        return decoded_objects
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return []

def validate_data(data):
    """Validates the decoded data."""
    if not data:
        return False
    if not re.match(r'^[A-Za-z0-9]+$', data):
        return False
    return True

def log_inventory(camera_id, item_id, timestamp):
    """Logs the inventory data to a CSV file."""
    try:
        file_exists = os.path.isfile(INVENTORY_LOG_FILE)
        with open(INVENTORY_LOG_FILE, 'a', newline='') as csvfile:
            fieldnames = ['camera_id', 'item_id', 'timestamp']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if not file_exists:
                writer.writeheader()
            writer.writerow({'camera_id': camera_id, 'item_id': item_id, 'timestamp': timestamp})
    except Exception as e:
        log_error(f"Inventory logging failed: {e}")

def log_error(message):
    """Logs an error message to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, 'a') as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Error logging failed: {e}")

def main():
    """Main function to run the QR code inventory system."""
    camera = initialize_camera(CAMERA_INDEX)
    if camera is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            frame = capture_frame(camera)
            if frame is None:
                time.sleep(CAPTURE_INTERVAL)
                continue

            decoded_objects = decode_qr_code(frame)
            for obj in decoded_objects:
                data = obj.data.decode('utf-8')
                if validate_data(data):
                    timestamp = datetime.datetime.now().isoformat()
                    log_inventory("Camera 1", data, timestamp)
                    print(f"Item ID: {data}, Timestamp: {timestamp}")
                else:
                    log_error(f"Invalid QR code data: {data}")

            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

