import pygame.mixer
from threading import Thread
from typing import Tuple, Optional

# Project-specific modules (replace with your actual modules)
import config  # type: ignore
import face  # type: ignore
import hardware  # type: ignore


class SoundPlayer:
    """Handles sound playback using Pygame mixer."""

    def __init__(self):
        try:
            pygame.mixer.init(frequency=48000, size=-16, channels=2, buffer=1024)
            self.sounds = {
                "welcome": pygame.mixer.Sound(config.WELCOME_SOUND_PATH),
                "wait": pygame.mixer.Sound(config.WAIT_SOUND_PATH),
                "later": pygame.mixer.Sound(config.LATER_SOUND_PATH),
            }
            self.channels = [pygame.mixer.Channel(i) for i in range(len(self.sounds))]
        except Exception as e:
            raise SoundInitializationError(f"Error initializing sound: {e}")

    def play(self, sound_name: str):
        """Plays a sound asynchronously."""
        try:
            sound = self.sounds[sound_name]
            channel = self.channels.pop(0)  # Get a free channel
            channel.play(sound)
            self.channels.append(channel)  # Return the channel to the pool after use
        except KeyError:
            raise InvalidSoundError(f"Sound '{sound_name}' not found.")
        except Exception as e:
            raise SoundPlaybackError(f"Error playing sound: {e}")


class FaceRecognizer:
    """Handles face recognition using OpenCV."""

    def __init__(self, model_path: str):
        try:
            self.model = cv2.face.EigenFaceRecognizer_create()
            self.model.read(model_path)
        except Exception as e:
            raise ModelLoadingError(f"Error loading face recognition model: {e}")

    def recognize(self, image) -> Tuple[bool, Optional[str]]:
        """Recognizes a face in the given image."""
        try:
            gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
            face_coords = face.detect_single(gray_image)

            if face_coords is None:
                return False, None  # Indicate no face found

            x, y, w, h = face_coords
            cropped_face = face.crop(gray_image, x, y, w, h)
            resized_face = face.resize(cropped_face)
            label, confidence = self.model.predict(resized_face)

            if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                return True, config.POSITIVE_LABEL  # Indicate positive recognition
            else:
                return False, None  # Indicate negative recognition

        except Exception as e:
            raise FaceRecognitionError(f"Error during face recognition: {e}")


class DoorController:
    """Manages the door locking mechanism."""

    def __init__(self):
        try:
            self.sound_player = SoundPlayer()
            self.face_recognizer = FaceRecognizer(config.TRAINING_FILE)
            self.camera = config.get_camera()
            self.locker = hardware.Locker()
        except (SoundInitializationError, ModelLoadingError) as e:
            print(f"Initialization error: {e}")
            sys.exit(1)  # Exit on critical initialization errors

    def run(self):
        """Main loop for door control."""
        try:
            while True:
                if self.locker.is_button_up() or self.locker.is_button_down():
                    if self.locker.is_button_up():
                        self._handle_positive_recognition()
                    else:  # Button down
                        self._handle_negative_recognition()
                time.sleep(0.1)
        except KeyboardInterrupt:
            print("Exiting...")
        finally:
            self._cleanup()

    def _handle_positive_recognition(self):
        """Handles positive recognition (unlock)."""
        print("Positive recognition. Unlocking...")
        self.locker.lock()

    def _handle_negative_recognition(self):
        """Handles negative recognition (lock)."""
        print("Negative recognition. Locking...")
        self.locker.unlock()

    def _cleanup(self):
        """Releases resources and performs cleanup."""
        try:
            self.camera.stop_preview()
            self.camera.close()
            pygame.mixer.quit()
        except Exception as e:
            print(f"Cleanup error: {e}")


# Custom Exception Classes for better error handling
class SoundInitializationError(Exception):
    pass


class InvalidSoundError(Exception):
    pass


class SoundPlaybackError(Exception):
    pass


class ModelLoadingError(Exception):
    pass


class FaceRecognitionError(Exception):
    pass


if __name__ == "__main__":
    door_controller = DoorController()
    door_controller.run()

