import time
import smbus

# Define the thermal zone file path
THERMAL_ZONE_FILE = '/sys/class/thermal/thermal_zone0/temp'

# Function to read the CPU temperature
def get_cpu_temperature():
    """Reads the CPU temperature from the thermal zone file."""
    try:
        with open(THERMAL_ZONE_FILE, 'r') as file:
            temp_millidegrees = file.read().strip()
            temp_celsius = float(temp_millidegrees) / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print('Error: Thermal zone file not found.')
        return None
    except PermissionError:
        print('Error: Permission denied when accessing thermal zone file.')
        return None
    except Exception as e:
        print(f'Error reading temperature: {e}')
        return None

# Main execution block
if __name__ == "__main__":
    # Initialize I2C bus (for potential future use with OLED)
    try:
        bus = smbus.SMBus(1)  # Use 1 for Raspberry Pi 5
        print("I2C bus initialized.")
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        bus = None  # Ensure bus is None if initialization fails

    try:
        # Main loop to continuously read and print the CPU temperature
        while True:
            temperature = get_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.2f} °C")
            time.sleep(2)  # Wait for 2 seconds before the next reading

    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("\nExiting program.")

    finally:
        # Perform cleanup actions here (if needed)
        if bus:
            try:
                bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        print("Program finished.")

