# Temperature monitoring script for Raspberry Pi using RS485
# Reads temperature from a USB RS485 adapter on /dev/ttyUSB0
import serial
import time

# RS485 configuration for the temperature sensor
RS485_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
DATA_BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1

def configure_rs485():
    """Sets up the serial port for RS485 communication."""
    try:
        rs485_connection = serial.Serial(
            RS485_PORT, BAUD_RATE, bytesize=DATA_BITS, parity=PARITY,
            stopbits=STOP_BITS, timeout=TIMEOUT
        )
        return rs485_connection
    except serial.SerialException as error:
        print(f"Error opening RS485 port: {error}")
        return None

def read_temperature(rs485_connection):
    """Reads temperature data from the RS485 sensor."""
    try:
        line = rs485_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature_value = float(line)
            print(f"Temperature: {temperature_value:.1f} C")
    except ValueError:
        print("Error: Malformed data received from sensor.")
    except serial.SerialException as error:
        print(f"Error reading from RS485 port: {error}")

def main():
    """Main function to continuously read and display temperature."""
    rs485_connection = configure_rs485()

    if rs485_connection is None:
        print("Failed to initialize RS485. Exiting.")
        return

    try:
        while True:
            read_temperature(rs485_connection)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nMonitoring stopped by user.")
    finally:
        if rs485_connection and rs485_connection.is_open:
            rs485_connection.close()
            print("RS485 port closed.")

if __name__ == "__main__":
    main()

