import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# Global variable to track if the program should exit
running = True

# Function to handle SIGINT and SIGTERM signals
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful exit."""
    global running
    print("Exiting program...")
    running = False

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def validate_data(temperature, humidity, pressure):
    """Validates weather data against predefined ranges."""
    if not (-40 <= temperature <= 85 and 0 <= humidity <= 100 and 800 <= pressure <= 1200):
        return False
    return True

def process_weather_data(serial_port):
    """Reads, validates, and prints weather data from the serial port."""
    try:
        while running:
            line = serial_port.readline().decode('ascii', errors='replace').strip()
            if line:
                try:
                    temperature, humidity, pressure = map(float, line.split(','))
                    if validate_data(temperature, humidity, pressure):
                        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                        print(f"{timestamp} - Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, Pressure: {pressure:.1f} hPa")
                    else:
                        print(f"Warning: Invalid data: {line}")
                except ValueError:
                    print(f"Warning: Malformed data: {line}")
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to initialize and run the weather data processing."""
    try:
        # Initialize serial port
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to serial port {SERIAL_PORT}")
            process_weather_data(ser)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

