import time
import RPi.GPIO as GPIO

# DHT22 sensor pin (BCM numbering)
DHT_PIN = 4

# Retry settings
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds

# Timeout for sensor response (in microseconds)
TIMEOUT = 100

# Initialize GPIO
GPIO.setmode(GPIO.BCM)


def read_dht22():
    """Reads temperature and humidity from DHT22 sensor using bit-banging."""

    def send_and_sleep(output, sleep_time):
        GPIO.output(DHT_PIN, output)
        time.sleep(sleep_time)

    def collect_input():
        """Collects sensor data from GPIO."""
        unchanged_count = 0
        max_unchanged_count = 100
        last = -1
        data = []
        while True:
            current = GPIO.input(DHT_PIN)
            data.append(current)
            if last != current:
                unchanged_count = 0
                last = current
            else:
                unchanged_count += 1
                if unchanged_count > max_unchanged_count:
                    break
        return data

    def parse_data(data):
        """Parses collected data into humidity and temperature."""
        pull_up_lengths = []
        if data[0] == 0 and data[1] == 1:
            for i in range(2, len(data)):
                current = data[i]
                count = 1
                while i + 1 < len(data) and data[i + 1] == current:
                    count += 1
                    i += 1
                pull_up_lengths.append(count)
            if len(pull_up_lengths) != 40:
                return None, None  # Invalid data length

