import time
import adafruit_dht
import board

# Configuration
DHT_PIN = board.D22  # BCM pin 22
READ_INTERVAL = 3  # seconds
RETRY_DELAY = 0.1  # seconds
MAX_RETRIES = 2

# Initialize DHT22 sensor
dht_device = adafruit_dht.DHT22(DHT_PIN)

def read_dht22():
    """Reads temperature and humidity from DHT22 sensor with retries."""
    for attempt in range(MAX_RETRIES + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                print(f"Attempt {attempt + 1}: Failed to read from DHT22 sensor.")
        except RuntimeError as error:
            # Errors happen fairly often, DHT's are hard to read, just keep going
            print(f"Attempt {attempt + 1}: RuntimeError: {error}")
        except Exception as error:
            dht_device.exit()
            raise error  # Re-raise unexpected errors
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    return None, None  # Return None if all retries fail

def display_readings(temperature, humidity):
    """Displays temperature and humidity readings."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
    else:
        print("Failed to retrieve data from DHT22 sensor.")

def main():
    """Main function to read and display DHT22 data."""
    try:
        while True:
            temperature, humidity = read_dht22()
            display_readings(temperature, humidity)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        dht_device.exit()
        print("DHT22 sensor resources released.")

if __name__ == "__main__":
    main()

