import time
import board
import busio
import adafruit_bmp280

# Initialize I2C bus and BMP280 sensor
i2c_bus = busio.I2C(board.SCL, board.SDA)
try:
    bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
except ValueError:
    print("Error: BMP280 sensor not found. Check wiring and I2C configuration.")
    exit()

# Collect baseline pressure over 10 seconds
print("Collecting baseline pressure...")
pressure_readings = []
for _ in range(10):
    try:
        pressure_readings.append(bmp280_sensor.pressure)
        time.sleep(1)
    except OSError:
        print("Error reading pressure. Check sensor connection.")
        time.sleep(1)

# Calculate baseline pressure (excluding first two readings)
if len(pressure_readings) > 2:
    baseline_pressure = sum(pressure_readings[2:]) / (len(pressure_readings) - 2)
else:
    print("Not enough pressure readings. Exiting.")
    exit()

# Main loop to read and display altitude
try:
    while True:
        try:
            current_pressure = bmp280_sensor.pressure
            altitude = 44330 * (1.0 - (current_pressure / baseline_pressure)**(1/5.255))
            print(f"Relative altitude: {altitude:.2f} meters")
            time.sleep(1)
        except OSError:
            print("Error reading pressure. Check sensor connection.")
            time.sleep(1)
except KeyboardInterrupt:
    print("Exiting program.")

