# Raspberry Pi Altitude Logger using BMP280 sensor
# Logs pressure and altitude to a file every second.
# Designed for STEM education, emphasizing clarity and simplicity.

import time
import board
import busio
import adafruit_bmp280

# Configuration
LOG_FILE = "altitude_log.txt"
SEA_LEVEL_PRESSURE = 1013.25  # Standard sea level pressure in hPa

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
        sensor.sea_level_pressure = SEA_LEVEL_PRESSURE
        return sensor
    except Exception as e:
        print(f"Error initializing BMP280 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads pressure and altitude from the sensor."""
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def log_data(log_file, pressure, altitude):
    """Logs the pressure and altitude data to a file."""
    try:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp} – Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n"
        with open(log_file, "a") as file:
            file.write(log_entry)
        print(log_entry.strip())  # Print to console, remove trailing newline
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to run the altitude logger."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        exit(1)

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        exit(1)

    try:
        next_reading_time = time.monotonic()
        while True:
            if time.monotonic() >= next_reading_time:
                pressure, altitude = read_sensor_data(sensor)

                if pressure is not None and altitude is not None:
                    log_data(LOG_FILE, pressure, altitude)

                next_reading_time += 1  # Schedule the next reading

            time.sleep(0.1)  # Short sleep to prevent busy-waiting

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or BMP280 in this library,
        # but including a placeholder for potential future expansion.
        print("Exiting program.")

if __name__ == "__main__":
    main()

