import time
import datetime
import logging
import os
import sys

try:
    import w1thermsensor
    import Adafruit_DHT
    import RPi.GPIO as GPIO
except ImportError as e:
    print(f"Error importing required libraries: {e}.  Ensure they are installed.")
    sys.exit(1)


# Configuration
DHT_PIN = 4  # BCM numbering
LED_PIN = 17  # BCM numbering
DHT_SENSOR = Adafruit_DHT.DHT22
TEMPERATURE_THRESHOLD_HIGH = 30.0
TEMPERATURE_THRESHOLD_LOW = 25.0
LOG_FILE = "hydroponics_data.log"
SLEEP_INTERVAL = 5  # seconds

# Initialize logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(LED_PIN, GPIO.OUT)
GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off initially

# Initialize 1-Wire sensor
try:
    ds18b20_sensor = w1thermsensor.W1ThermSensor()
except w1thermsensor.errors.NoSensorFoundError:
    logging.error("DS18B20 sensor not found. Check wiring and 1-Wire configuration.")
    ds18b20_sensor = None  # Handle the case where the sensor is not found
except Exception as e:
    logging.error(f"Error initializing DS18B20 sensor: {e}")
    ds18b20_sensor = None


def read_dht22():
    """Reads temperature and humidity from DHT22 sensor."""
    try:
        humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
        if humidity is not None and temperature is not None:
            return temperature, humidity
        else:
            logging.warning("DHT22: Failed to read sensor data.")
            return None, None
    except Exception as e:
        logging.error(f"DHT22: Error reading sensor: {e}")
        return None, None


def read_ds18b20():
    """Reads temperature from DS18B20 sensor."""
    if ds18b20_sensor is None:
        logging.warning("DS18B20 sensor is not initialized.")
        return None
    try:
        temperature = ds18b20_sensor.get_temperature()
        return temperature
    except w1thermsensor.errors.SensorNotReadyError:
        logging.warning("DS18B20: Sensor not ready.")
        return None
    except Exception as e:
        logging.error(f"DS18B20: Error reading sensor: {e}")
        return None


def control_led(temperature):
    """Controls the LED based on temperature."""
    try:
        if temperature is not None:
            if temperature > TEMPERATURE_THRESHOLD_HIGH:
                GPIO.output(LED_PIN, GPIO.HIGH)  # Turn LED on
            elif temperature < TEMPERATURE_THRESHOLD_LOW:
                GPIO.output(LED_PIN, GPIO.LOW)  # Turn LED off
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")


def log_data(dht22_temperature, dht22_humidity, ds18b20_temperature):
    """Logs sensor data to the log file."""
    try:
        log_message = f"DHT22 Temperature: {dht22_temperature:.2f}°C, DHT22 Humidity: {dht22_humidity:.2f}%, DS18B20 Temperature: {ds18b20_temperature:.2f}°C"
        logging.info(log_message)
    except Exception as e:
        logging.error(f"Error logging data: {e}")


def main():
    """Main function to read sensors, control LED, and log data."""
    try:
        while True:
            # Read sensor data
            dht22_temperature, dht22_humidity = read_dht22()
            ds18b20_temperature = read_ds18b20()

            # Control LED
            if dht22_temperature is not None:
                control_led(dht22_temperature)

            # Log data
            log_data(dht22_temperature, dht22_humidity, ds18b20_temperature)

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO on exit
        GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

