import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom protocol module

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global variables
log_file_path = DEFAULT_LOG_FILE
receive_thread = None
running = True

# Help messages
help_messages = {
    "start": "Usage: start <filename>",
    "stop": "Usage: stop",
    "send": "Usage: send <data>",
    "write": "Usage: write <data>",
    "display": "Usage: display",
    "help": "Usage: help [command]",
    "exit": "Usage: exit",
}


def log_message(message):
    """Append a message to the log file."""
    try:
        with open(log_file_path, "a") as log_file:
            log_file.write(message + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")


def receive_data():
    """Continuously receive data and log it to the file."""
    try:
        while running:
            data = DOG.receive()  # Replace with your DOGProtocol receive function
            if data:  # Check if data is not empty
                log_message(data)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Error in receive thread: {e}")
    finally:
        print("Receive thread stopped.")


def start_receiving(filename):
    """Start the data receiving thread."""
    global log_file_path, receive_thread, running

    if receive_thread is not None and receive_thread.is_alive():
        print("Receiving already started.")
        return

    log_file_path = filename
    running = True  # Ensure running is True before starting the thread

    try:
        # Clear existing log file
        open(log_file_path, "w").close()
    except Exception as e:
        print(f"Error creating/clearing log file: {e}")
        return

    receive_thread = threading.Thread(target=receive_data, name="ReceiveThread", daemon=True)
    receive_thread.start()
    print(f"Started receiving data, logging to {log_file_path}")


def stop_receiving():
    """Stop the data receiving thread."""
    global receive_thread, running

    running = False  # Signal the thread to stop

    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join()  # Wait for the thread to finish
        receive_thread = None
        print("Stopped receiving data.")
    else:
        print("Receiving was not active.")


def send_data(data):
    """Send data using the DOG protocol."""
    try:
        DOG.send(data)  # Replace with your DOGProtocol send function
        print(f"Sent data: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Write data directly to the log file."""
    log_message(data)
    print(f"Wrote to log: {data}")


def display_log():
    """Display the contents of the log file."""
    try:
        with open(log_file_path, "r") as log_file:
            print(log_file.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error reading log file: {e}")


def display_help(command=None):
    """Display help information."""
    if command:
        message = help_messages.get(command)
        if message:
            print(message)
        else:
            print(f"No help found for command: {command}")
    else:
        print("Available commands:")
        for cmd in help_messages:
            print(f"  {cmd}")
        print("Use 'help <command>' for more information.")


def cleanup():
    """Clean up resources before exiting."""
    print("Cleaning up...")
    stop_receiving()
    GPIO.cleanup()  # Clean up GPIO pins
    print("Exiting.")


def main():
    """Main function to handle user input and program flow."""
    global running

    try:
        GPIO.setmode(GPIO.BCM)  # Initialize GPIO (adjust as needed)

        while running:
            command = input("Enter command: ").strip().split()
            if not command:
                continue

            action = command[0].lower()
            args = command[1:]

            if action == "start":
                if len(args) == 1:
                    start_receiving(args[0])
                else:
                    print(help_messages["start"])
            elif action == "stop":
                stop_receiving()
            elif action == "send":
                send_data(" ".join(args))  # Join arguments for data
            elif action == "write":
                write_to_log(" ".join(args))
            elif action == "display":
                display_log()
            elif action == "help":
                if len(args) == 1:
                    display_help(args[0])
                else:
                    display_help()
            elif action == "exit":
                running = False
                break
            else:
                print("Invalid command. Try 'help'.")

    except KeyboardInterrupt:
        print("\nKeyboard interrupt detected.")
        running = False
    finally:
        cleanup()


if __name__ == "__main__":
    main()

