import RPi.GPIO as GPIO
import time
import sys

# Pin connected to the fan's PWM control (BCM numbering)
FAN_PIN = 12

# PWM frequency for the fan (Hz)
PWM_FREQUENCY = 25000

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
except Exception as e:
    print(f"Error initializing GPIO: {e}")
    sys.exit(1)

# Create PWM instance
try:
    fan_pwm = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
    fan_pwm.start(0)  # Start with 0% duty cycle (fan off)
except Exception as e:
    print(f"Error creating PWM instance: {e}")
    GPIO.cleanup()
    sys.exit(1)


def set_fan_speed(speed_percent):
    """Sets the fan speed as a percentage of maximum speed."""
    try:
        if 0 <= speed_percent <= 100:
            fan_pwm.ChangeDutyCycle(speed_percent)
            print(f"Fan speed set to {speed_percent}%")
        else:
            print("Invalid speed. Please enter a value between 0 and 100.")
    except Exception as e:
        print(f"Error setting fan speed: {e}")


def main():
    """Main function to handle user input and control fan speed."""
    try:
        while True:
            try:
                user_input = input("Enter fan speed (0-100) or 'q' to quit: ")
                if user_input.lower() == 'q':
                    break
                fan_speed = float(user_input)
                set_fan_speed(fan_speed)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except KeyboardInterrupt:  # Handle Ctrl+C gracefully
        print("\nExiting program.")
    finally:  # Always clean up GPIO
        fan_pwm.stop()
        GPIO.cleanup()
        print("GPIO cleaned up.")


if __name__ == "__main__":
    main()

