import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Configuration constants
LED_GPIO_PIN = 18
PWM_FREQUENCY_HZ = 1000
RETRY_DELAY_SECONDS = 1

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing light sensor: {e}")
        return None

def initialize_gpio(led_pin, pwm_frequency):
    """Initialize the GPIO pin for LED control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        pwm_channel = GPIO.PWM(led_pin, pwm_frequency)
        pwm_channel.start(0)
        return pwm_channel
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None

def read_light_level(sensor):
    """Read the light level from the sensor and convert to lux."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def set_led_brightness(pwm_channel, lux_value, led_pin):
    """Set the LED brightness based on the lux value."""
    try:
        if lux_value is not None:
            brightness = min(100, max(0, lux_value / 10))  # Scale lux to 0-100%
            pwm_channel.ChangeDutyCycle(brightness)
            print(f"Lux: {lux_value:.2f}, Brightness: {brightness:.2f}%")
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to control LED brightness based on ambient light."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return

    pwm_channel = initialize_gpio(LED_GPIO_PIN, PWM_FREQUENCY_HZ)
    if pwm_channel is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            lux = read_light_level(light_sensor)
            set_led_brightness(pwm_channel, lux, LED_GPIO_PIN)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        pwm_channel.stop()
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C resources released.")

if __name__ == "__main__":
    main()

