from gpiozero import DigitalOutputDevice, PWMOutputDevice, exc
from enum import Enum

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Motor Driver Constants (BCM numbering)
LEFT_MOTOR_FORWARD_PIN = 17
LEFT_MOTOR_BACKWARD_PIN = 18
RIGHT_MOTOR_FORWARD_PIN = 22
RIGHT_MOTOR_BACKWARD_PIN = 23
LEFT_MOTOR_ENABLE_PIN = 12  # PWM
RIGHT_MOTOR_ENABLE_PIN = 13 # PWM

# Chassis Controller Constants
FORWARD_THRESHOLD = 20
REVERSE_THRESHOLD = -20
TURN_THRESHOLD = 10

# Global flag for graceful shutdown
shutdown_flag = False

class MotorDirection(Enum):
    FORWARD = 1
    BACKWARD = 2
    STOP = 3

class MotorFault(Exception):
    """Custom exception for motor faults."""
    pass

class Motor:
    """Represents a single DC motor with error handling and PWM control."""

    def __init__(self, forward_pin, backward_pin, enable_pin, motor_name):
        self.motor_name = motor_name
        try:
            self.forward_pin = DigitalOutputDevice(forward_pin)
            self.backward_pin = DigitalOutputDevice(backward_pin)
            self.enable_pin = PWMOutputDevice(enable_pin, True, 0, 1000) # Start disabled
            self.is_inverted = False # Basic calibration
        except exc.GPIODeviceError as e:
            logging.error(f"Error initializing motor {self.motor_name}: {e}")
            raise

    def set_direction(self, direction):
        """Sets the direction of the motor."""
        try:
            if direction == MotorDirection.FORWARD:
                self.forward_pin.on()
                self.backward_pin.off()
            elif direction == MotorDirection.BACKWARD:
                self.forward_pin.off()
                self.backward_pin.on()
            elif direction == MotorDirection.STOP:
                self.forward_pin.off()
                self.backward_pin.off()
            else:
                raise ValueError("Invalid motor direction.")
        except Exception as e:
            logging.error(f"Error setting direction for motor {self.motor_name}: {e}")
            raise

    def set_speed(self, speed_fraction):
        """Sets the speed of the motor using PWM."""
        try:
            if not 0 <= speed_fraction <= 1:
                raise ValueError("Speed fraction must be between 0 and 1.")
            self.enable_pin.value = speed_fraction
        except Exception as e:
            logging.error(f"Error setting speed for motor {self.motor_name}: {e}")
            raise

    def invert(self):
        """Inverts the motor direction."""
        self.is_inverted = not self.is_inverted
        logging.warning(f"Motor {self.motor_name} inversion toggled. Current state: {self.is_inverted}")

    def stop(self):
        """Stops the motor."""
        self.set_direction(MotorDirection.STOP)

    def close(self):
        """Releases GPIO resources."""
        try:
            self.stop()
            self.enable_pin.close()
            self.forward_pin.close()
            self.backward_pin.close()
        except Exception as e:
            logging.error(f"Error closing motor {self.motor_name}: {e}")


class ChassisController:
    """Controls a robot chassis with two motors, using a functional approach."""

    def __init__(self, left_motor, right_motor):
        self.left_motor = left_motor
        self.right_motor = right_motor

    def _calculate_speed_fraction(self, tilt_angle):
        """Calculates the speed fraction based on the tilt angle."""
        return max(0.0, min(1.0, abs(tilt_angle) / 90.0)) # Normalize to 0-1 range

    def _motor_action(self, motor, direction, speed_fraction):
        """Applies an action (direction and speed) to a motor."""
        try:
            motor.set_direction(direction)
            motor.set_speed(speed_fraction)
        except Exception as e:
            logging.error(f"Motor action failed: {e}")
            raise MotorFault(f"Motor action failed: {e}")

    def drive_forward(self, speed_fraction):
        """Drives the chassis forward."""
        try:
            self._motor_action(self.left_motor, MotorDirection.FORWARD, speed_fraction)
            self._motor_action(self.right_motor, MotorDirection.FORWARD, speed_fraction)
            logging.debug(f"Driving forward at speed: {speed_fraction}")
        except MotorFault as e:
            raise e

    def turn_left(self, speed_fraction):
        """Turns the chassis left."""
        try:
            self._motor_action(self.left_motor, MotorDirection.BACKWARD, speed_fraction)
            self._motor_action(self.right_motor, MotorDirection.FORWARD, speed_fraction)
            logging.debug(f"Turning left at speed: {speed_fraction}")
        except MotorFault as e:
            raise e

    def turn_right(self, speed_fraction):
        """Turns the chassis right."""
        try:
            self._motor_action(self.left_motor, MotorDirection.FORWARD, speed_fraction)
            self._motor_action(self.right_motor, MotorDirection.BACKWARD, speed_fraction)
            logging.debug(f"Turning right at speed: {speed_fraction}")
        except MotorFault as e:
            raise e

    def reverse(self, speed_fraction):
        """Reverses the chassis."""
        try:
            self._motor_action(self.left_motor, MotorDirection.BACKWARD, speed_fraction)
            self._motor_action(self.right_motor, MotorDirection.BACKWARD, speed_fraction)
            logging.debug(f"Reversing at speed: {speed_fraction}")
        except MotorFault as e:
            raise e

    def stop_all(self):
        """Stops all motors."""
        try:
            self._motor_action(self.left_motor, MotorDirection.STOP, 0)
            self._motor_action(self.right_motor, MotorDirection.STOP, 0)
            logging.debug("Stopping all motors.")
        except MotorFault as e:
            raise e

    def handle_tilt(self, tilt_angle):
        """Handles the chassis control logic based on the tilt angle."""
        try:
            speed_fraction = self._calculate_speed_fraction(tilt_angle)

            if tilt_angle > FORWARD_THRESHOLD:
                self.drive_forward(speed_fraction)
            elif tilt_angle < REVERSE_THRESHOLD:
                self.reverse(speed_fraction)
            elif -TURN_THRESHOLD < tilt_angle < TURN_THRESHOLD: #Deadband
                self.stop_all()
            elif tilt_angle < -TURN_THRESHOLD:
                self.turn_left(speed_fraction)
            elif tilt_angle > TURN_THRESHOLD:
                self.turn_right(speed_fraction)
            else:
                self.stop_all()

        except MotorFault as e:
            logging.error(f"Chassis control failed: {e}")
            self.stop_all() # Emergency stop


def simulate_tilt_sensor():
    """Simulates a tilt sensor, returning a sequence of tilt angles."""
    return [25, -25, 0, 30, -15, 40, -30, 10]

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global shutdown_flag
    logging.info("Signal received, shutting down gracefully...")
    shutdown_flag = True

def main():
    """Main function to initialize and run the chassis controller."""
    global shutdown_flag

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        # Initialize motors
        left_motor = Motor(LEFT_MOTOR_FORWARD_PIN, LEFT_MOTOR_BACKWARD_PIN, LEFT_MOTOR_ENABLE_PIN, "Left")
        right_motor = Motor(RIGHT_MOTOR_FORWARD_PIN, RIGHT_MOTOR_BACKWARD_PIN, RIGHT_MOTOR_ENABLE_PIN, "Right")

        # Initialize chassis controller
        chassis = ChassisController(left_motor, right_motor)

        # Simulate tilt sensor data and control the chassis
        for tilt_angle in simulate_tilt_sensor():
            if shutdown_flag:
                break

            logging.info(f"Tilt angle: {tilt_angle} degrees")
            chassis.handle_tilt(tilt_angle)
            time.sleep(0.5)  # Simulate control loop delay

    except MotorFault as e:
        logging.critical(f"Fatal motor error: {e}")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        # Ensure motors are stopped and GPIO resources are released
        logging.info("Cleaning up and exiting...")
        if 'chassis' in locals():
            chassis.stop_all()
        if 'left_motor' in locals():
            left_motor.close()
        if 'right_motor' in locals():
            right_motor.close()
        logging.info("Cleanup complete.")

if __name__ == "__main__":
    main()

