import RPi.GPIO as GPIO
import time
import random

# Pin connected to the SW-420 digital output (BCM numbering)
VIBRATION_SENSOR_PIN = 17

# Threshold for predictive maintenance (average amplitude)
MAINTENANCE_THRESHOLD = 7.5

# Number of samples to average for trend analysis
NUM_SAMPLES = 6

# Delay between sensor readings (seconds)
READ_DELAY = 0.3


def setup_gpio():
    """Set up the GPIO pin for the vibration sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(VIBRATION_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def read_vibration_level():
    """Read the vibration sensor and return a simulated amplitude."""
    # Active-low: LOW means vibration detected
    if GPIO.input(VIBRATION_SENSOR_PIN) == GPIO.LOW:
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)


def analyze_trend(amplitude_values):
    """Calculate the average amplitude and check for maintenance needs."""
    average_amplitude = sum(amplitude_values) / len(amplitude_values)
    if average_amplitude > MAINTENANCE_THRESHOLD:
        print("Maintenance recommended: wear trend is high")
    else:
        print("Component healthy: no action needed")


def main():
    """Main function to run the predictive maintenance loop."""
    setup_gpio()
    amplitude_readings = []
    try:
        for _ in range(NUM_SAMPLES):
            amplitude = read_vibration_level()
            amplitude_readings.append(amplitude)
            time.sleep(READ_DELAY)
        analyze_trend(amplitude_readings)
    except Exception as error:
        print(f"An error occurred: {error}")
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    main()

