import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
PUMP_PIN = 17
DRY_THRESHOLD = 500
SLEEP_INTERVAL = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def initialize_gpio(pin):
    """Initialize the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Ensure pump is initially off

def read_moisture_level(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture level: {e}")
        return None

def control_water_pump(pin, moisture_level, threshold):
    """Control the water pump based on the moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < threshold:
                GPIO.output(pin, GPIO.HIGH)  # Activate pump
                pump_status = "ON"
            else:
                GPIO.output(pin, GPIO.LOW)  # Deactivate pump
                pump_status = "OFF"
            return pump_status
        else:
            return "Unknown"
    except Exception as e:
        print(f"Error controlling water pump: {e}")
        return "Error"

def main():
    """Main function to monitor soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    initialize_gpio(PUMP_PIN)

    try:
        while True:
            moisture = read_moisture_level(sensor)
            pump_state = control_water_pump(PUMP_PIN, moisture, DRY_THRESHOLD)

            if moisture is not None:
                print(f"Moisture: {moisture}, Pump: {pump_state}")
            else:
                print("Moisture: Unavailable, Pump: Unknown")

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        GPIO.output(PUMP_PIN, GPIO.LOW)  # Ensure pump is off on exit
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C resources released.")

if __name__ == "__main__":
    main()

