import smbus2 as smbus

class I2CDevice:
    """
    A generic I2C device driver helper class for the Raspberry Pi.
    Provides a clean API for reading and writing registers over I2C.
    """

    def __init__(self, address, bus_number=1):
        """
        Initialise the I2C device at the given address on the specified bus.

        :param address: The I2C address of the device (integer).
        :param bus_number: The I2C bus number (integer), default is 1.
        """
        # Store the device address and bus number
        self.device_address = address
        self.bus_number = bus_number
        self.i2c_bus = None

    def open_bus(self):
        """Open the I2C bus and probe for device presence."""
        try:
            # Create an smbus2 instance for the specified bus
            self.i2c_bus = smbus.SMBus(self.bus_number)
            # Try to read a byte from the device to check if it is present
            self.i2c_bus.read_byte(self.device_address)
        except OSError as os_error:
            # Handle I/O errors during the probe
            raise RuntimeError(
                f"Failed to probe I2C device at address 0x{self.device_address:02X}: {os_error}"
            ) from os_error
        except IOError as io_error:
            # Handle I/O errors during the probe
            raise RuntimeError(
                f"Failed to probe I2C device at address 0x{self.device_address:02X}: {io_error}"
            ) from io_error

    def close(self):
        """Close the I2C bus connection."""
        if self.i2c_bus is not None:
            try:
                self.i2c_bus.close()
            except Exception as close_error:
                # Log the error but do not re-raise, as closing is best-effort
                print(f"Error closing I2C bus: {close_error}")
            finally:
                self.i2c_bus = None

    def write_byte(self, register, value):
        """
        Write a single byte to the specified register.

        :param register: The register address to write to (integer).
        :param value: The byte value to write (integer).
        """
        if self.i2c_bus is None:
            raise RuntimeError("I2C bus not open. Call open_bus() first.")
        try:
            self.i2c_bus.write_byte_data(self.device_address, register, value)
        except OSError as os_error:
            raise RuntimeError(
                f"Failed to write byte 0x{value:02X} to register 0x{register:02X}: {os_error}"
            ) from os_error
        except IOError as io_error:
            raise RuntimeError(
                f"Failed to write byte 0x{value:02X} to register 0x{register:02X}: {io_error}"
            ) from io_error

    def read_byte(self, register):
        """
        Read a single byte from the specified register.

        :param register: The register address to read from (integer).
        :return: The byte value read from the register (integer).
        """
        if self.i2c_bus is None:
            raise RuntimeError("I2C bus not open. Call open_bus() first.")
        try:
            return self.i2c_bus.read_byte_data(self.device_address, register)
        except OSError as os_error:
            raise RuntimeError(
                f"Failed to read byte from register 0x{register:02X}: {os_error}"
            ) from os_error
        except IOError as io_error:
            raise RuntimeError(
                f"Failed to read byte from register 0x{register:02X}: {io_error}"
            ) from io_error

    def __enter__(self):
        """Context manager entry point, opens the I2C bus."""
        self.open_bus()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Context manager exit point, closes the I2C bus."""
        self.close()


if __name__ == "__main__":
    # Example usage of the I2CDevice class
    try:
        # Create an I2C device instance for a device at address 0x50
        i2c_device = I2CDevice(address=0x50, bus_number=1)
        # Open the I2C bus and probe for the device
        i2c_device.open_bus()
        # Write a value to register 0x01
        i2c_device.write_byte(register=0x01, value=0x42)
        # Read a value from register 0x01
        read_value = i2c_device.read_byte(register=0x01)
        print(f"Read value: 0x{read_value:02X}")
    except RuntimeError as runtime_error:
        # Handle any runtime errors that occur
        print(f"Runtime error: {runtime_error}")
    finally:
        # Ensure the I2C bus is closed, even if errors occur
        i2c_device.close()

