#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus
from datetime import datetime, timedelta
import logging
import os
import signal
import time

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_I2C_ADDRESS = 0x68
DS1338_SECONDS_REGISTER = 0x00
DS1338_MINUTES_REGISTER = 0x01
DS1338_HOURS_REGISTER = 0x02
DS1338_DAY_OF_WEEK_REGISTER = 0x03
DS1338_DAY_OF_MONTH_REGISTER = 0x04
DS1338_MONTH_REGISTER = 0x05
DS1338_YEAR_REGISTER = 0x06
DS1338_CONTROL_REGISTER = 0x07
DS1338_STATUS_REGISTER = 0x0F  # Added Status Register address

# Constants for 12-hour format
AM = 0x00
PM = 0x40

# Constants for century
CENTURY_1900 = 19
CENTURY_2000 = 20

# Global flag for SIGINT/SIGTERM
SHUTDOWN_FLAG = False

def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logger.exception("Invalid BCD value provided")
        raise

def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)

def register_write(i2c_bus, register, data):
    """Writes data to a specific register."""
    try:
        i2c_bus.write_byte_data(DS1338_I2C_ADDRESS, register, data)
    except OSError as e:
        logger.error(f"I2C write error: {e}")
        raise

def register_read(i2c_bus, register):
    """Reads data from a specific register."""
    try:
        return i2c_bus.read_byte_data(DS1338_I2C_ADDRESS, register)
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        raise

def check_oscillator_running(i2c_bus):
    """Checks if the oscillator is running by reading the status register."""
    status = register_read(i2c_bus, DS1338_STATUS_REGISTER)
    return (status & 0x80) == 0

def read_all(i2c_bus):
    """Reads all RTC registers and returns a dictionary."""
    try:
        data = {}
        data['seconds'] = register_read(i2c_bus, DS1338_SECONDS_REGISTER)
        data['minutes'] = register_read(i2c_bus, DS1338_MINUTES_REGISTER)
        data['hours'] = register_read(i2c_bus, DS1338_HOURS_REGISTER)
        data['day_of_week'] = register_read(i2c_bus, DS1338_DAY_OF_WEEK_REGISTER)
        data['day_of_month'] = register_read(i2c_bus, DS1338_DAY_OF_MONTH_REGISTER)
        data['month'] = register_read(i2c_bus, DS1338_MONTH_REGISTER)
        data['year'] = register_read(i2c_bus, DS1338_YEAR_REGISTER)
        return data
    except OSError as e:
        logger.error(f"I2C read error during full read: {e}")
        raise

def read_datetime(i2c_bus, century=CENTURY_2000):
    """Reads the date and time from the RTC and returns a datetime object."""
    try:
        data = read_all(i2c_bus)
        year = century + bcd_to_int(data['year'])
        month = bcd_to_int(data['month'])
        day = bcd_to_int(data['day_of_month'])
        hour = bcd_to_int(data['hours'] & 0x3F)  # Ensure 24-hour format
        minute = bcd_to_int(data['minutes'])
        second = bcd_to_int(data['seconds'] & 0x7F)  # Clear the CH bit
        return datetime(year, month, day, hour, minute, second)
    except (ValueError, TypeError) as e:
        logger.error(f"Error converting RTC data to datetime: {e}")
        raise

def write_all(i2c_bus, seconds=None, minutes=None, hours=None, day_of_week=None,
              day_of_month=None, month=None, year=None):
    """Writes all RTC registers.  Validates input values."""

    if seconds is not None:
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59.")
        register_write(i2c_bus, DS1338_SECONDS_REGISTER, int_to_bcd(seconds))

    if minutes is not None:
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59.")
        register_write(i2c_bus, DS1338_MINUTES_REGISTER, int_to_bcd(minutes))

    if hours is not None:
        if not 0 <= hours <= 23:
            raise ValueError("Hours must be between 0 and 23.")
        register_write(i2c_bus, DS1338_HOURS_REGISTER, int_to_bcd(hours))

    if day_of_week is not None:
        if not 1 <= day_of_week <= 7:
            raise ValueError("Day of week must be between 1 and 7.")
        register_write(i2c_bus, DS1338_DAY_OF_WEEK_REGISTER, int_to_bcd(day_of_week))

    if day_of_month is not None:
        if not 1 <= day_of_month <= 31:
            raise ValueError("Day of month must be between 1 and 31.")
        register_write(i2c_bus, DS1338_DAY_OF_MONTH_REGISTER, int_to_bcd(day_of_month))

    if month is not None:
        if not 1 <= month <= 12:
            raise ValueError("Month must be between 1 and 12.")
        register_write(i2c_bus, DS1338_MONTH_REGISTER, int_to_bcd(month))

    if year is not None:
        if not 0 <= year <= 99:
            raise ValueError("Year must be between 0 and 99.")
        register_write(i2c_bus, DS1338_YEAR_REGISTER, int_to_bcd(year))

def write_datetime(i2c_bus, dt, century=CENTURY_2000):
    """Writes the date and time to the RTC from a datetime object."""
    try:
        register_write(i2c_bus, DS1338_SECONDS_REGISTER, int_to_bcd(dt.second))
        register_write(i2c_bus, DS1338_MINUTES_REGISTER, int_to_bcd(dt.minute))
        register_write(i2c_bus, DS1338_HOURS_REGISTER, int_to_bcd(dt.hour))
        register_write(i2c_bus, DS1338_DAY_OF_WEEK_REGISTER, int_to_bcd(dt.isoweekday()))
        register_write(i2c_bus, DS1338_DAY_OF_MONTH_REGISTER, int_to_bcd(dt.day))
        register_write(i2c_bus, DS1338_MONTH_REGISTER, int_to_bcd(dt.month))
        register_write(i2c_bus, DS1338_YEAR_REGISTER, int_to_bcd(dt.year % century))
    except (ValueError, TypeError) as e:
        logger.error(f"Error converting datetime to RTC data: {e}")
        raise

def initialize_rtc(i2c_bus):
    """Initializes the RTC, checking for oscillator presence and setting the time if necessary."""
    try:
        if not check_oscillator_running(i2c_bus):
            logger.warning("DS1338 oscillator is not running. Ensure the RTC is powered on.")
            return False

        # Check if the current time is valid (year > 2000)
        try:
            current_time = read_datetime(i2c_bus)
            if current_time.year > 2000:
                logger.info("RTC time is already set.")
                return True
        except Exception as e:
            logger.info(f"RTC time is not set or invalid: {e}")

        # Set the RTC to a default time if it's not set
        default_time = datetime(2023, 1, 1, 0, 0, 0)
        write_datetime(i2c_bus, default_time)
        logger.info("RTC time set to default: 2023-01-01 00:00:00")
        return True

    except OSError as e:
        logger.error(f"I2C error during initialization: {e}")
        return False
    except Exception as e:
        logger.error(f"An unexpected error occurred during initialization: {e}")
        return False

def signal_handler(signum, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global SHUTDOWN_FLAG
    logger.info("Received signal, shutting down gracefully...")
    SHUTDOWN_FLAG = True

def main():
    """Main function to demonstrate RTC functionality."""
    global SHUTDOWN_FLAG

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        # Initialize I2C bus
        i2c_bus = smbus.SMBus(1)  # Use 1 for Raspberry Pi 2 and later

        # Initialize the RTC
        if not initialize_rtc(i2c_bus):
            logger.error("RTC initialization failed. Exiting.")
            return

        # Main loop
        while not SHUTDOWN_FLAG:
            try:
                # Read the current time from the RTC
                current_time = read_datetime(i2c_bus)
                logger.info(f"Current RTC time: {current_time.strftime('%Y-%m-%d %H:%M:%S')}")

                # Wait for 1 second
                time.sleep(1)

            except OSError as e:
                logger.error(f"I2C error in main loop: {e}")
                time.sleep(1)  # Wait before retrying
            except Exception as e:
                logger.error(f"An unexpected error occurred: {e}")
                time.sleep(1)

    except FileNotFoundError:
        logger.error("I2C bus not found.  Ensure I2C is enabled.")
    except Exception as e:
        logger.error(f"An unexpected error occurred during main: {e}")
    finally:
        try:
            i2c_bus.close()
            logger.info("I2C bus closed.")
        except Exception as e:
            logger.error(f"Error closing I2C bus: {e}")
        logger.info("Exiting program.")

if __name__ == "__main__":
    main()

