#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a driver for the DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus
from datetime import datetime, timezone
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DS1338Error(Exception):
    """Custom exception for DS1338 related errors."""
    pass

def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        raise DS1338Error("Invalid BCD value provided") from None

def int_to_bcd(integer_value):
    """Converts an integer to BCD format."""
    if not 0 <= integer_value <= 99:
        raise DS1338Error("Integer value must be between 0 and 99 for BCD conversion.")
    return (integer_value // 10 << 4) | (integer_value % 10)

class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    # Register addresses
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07
    REG_STATUS = 0x0F  # Added Status Register address

    def __init__(self, i2c_bus_number=1, device_address=0x68):
        """Initializes the DS1338 driver."""
        self.i2c_bus_number = i2c_bus_number
        self.device_address = device_address
        try:
            self.bus = smbus.SMBus(self.i2c_bus_number)
        except FileNotFoundError as e:
            raise DS1338Error(f"I2C bus {self.i2c_bus_number} not found: {e}") from None
        except Exception as e:
            raise DS1338Error(f"Failed to initialize I2C bus: {e}") from None
        logging.info("DS1338 driver initialized successfully.")

    def _write_register(self, register_address, data):
        """Writes data to a specific register."""
        try:
            self.bus.write_byte_data(self.device_address, register_address, data)
        except IOError as e:
            raise DS1338Error(f"Failed to write to register 0x{register_address:02X}: {e}") from None

    def _read_register(self, register_address):
        """Reads data from a specific register."""
        try:
            return self.bus.read_byte_data(self.device_address, register_address)
        except IOError as e:
            raise DS1338Error(f"Failed to read from register 0x{register_address:02X}: {e}") from None

    def _read_time_register(self, register_address):
        """Reads and decodes a time register (BCD)."""
        return bcd_to_int(self._read_register(register_address))

    def read_all(self):
        """Reads all time registers and returns them as a tuple."""
        try:
            year = self._read_time_register(self.REG_YEAR)
            month = self._read_time_register(self.REG_MONTH)
            date = self._read_time_register(self.REG_DATE)
            day = self._read_time_register(self.REG_DAY)
            hours = self._read_time_register(self.REG_HOURS) & 0x3F  # Ensure 24-hour mode
            minutes = self._read_time_register(self.REG_MINUTES)
            seconds = self._read_time_register(self.REG_SECONDS) & 0x7F  # Clear CH bit
            return year, month, date, day, hours, minutes, seconds
        except DS1338Error as e:
            raise DS1338Error(f"Failed to read all time registers: {e}") from None


    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year  # Correct year calculation
            return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except ValueError as e:  # Catch invalid date/time values
            raise DS1338Error(f"Invalid date/time data read from RTC: {e}") from None
        except DS1338Error as e:
            raise DS1338Error(f"Failed to read datetime: {e}") from None


    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Writes all time registers."""
        try:
            # Validate input values before writing
            if not all(0 <= val <= limit for val, limit in [(year % 100, 99), (month, 12), (date, 31), (day, 7), (hours, 23), (minutes, 59), (seconds, 59)]):
                raise ValueError("Invalid time/date value provided.")

            self._write_register(self.REG_SECONDS, int_to_bcd(seconds))
            self._write_register(self.REG_MINUTES, int_to_bcd(minutes))
            self._write_register(self.REG_HOURS, int_to_bcd(hours))  # 24-hour mode
            self._write_register(self.REG_DAY, int_to_bcd(day))
            self._write_register(self.REG_DATE, int_to_bcd(date))
            self._write_register(self.REG_MONTH, int_to_bcd(month))
            self._write_register(self.REG_YEAR, int_to_bcd(year % 100))
        except ValueError as e:
            raise DS1338Error(f"Invalid input data: {e}") from None
        except DS1338Error as e:
            raise DS1338Error(f"Failed to write all time registers: {e}") from None


    def write_datetime(self, dt):
        """Writes a datetime object to the RTC."""
        try:
            if not dt.tzinfo:
                raise ValueError("Datetime object must have timezone information.")
            self.write_all(dt.year % 100, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)
        except ValueError as e:
            raise DS1338Error(f"Invalid datetime object provided: {e}") from None
        except DS1338Error as e:
            raise DS1338Error(f"Failed to write datetime: {e}") from None


    def close(self):
        """Closes the I2C bus connection."""
        try:
            self.bus.close()
            logging.info("I2C bus connection closed.")
        except AttributeError:  # bus might not be initialized if __init__ failed
            pass
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")


    def __enter__(self):
        """Context manager entry point."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, ensuring the I2C bus is closed."""
        self.close()
        return False  # Re-raise any exceptions


if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            current_datetime = rtc.read_datetime()
            print(f"Current date and time: {current_datetime}")
    except DS1338Error as e:
        logging.error(f"DS1338 error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

