import serial
import time
import RPi.GPIO as GPIO

# Configure the serial port for the water flow sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

# GPIO pin for the flow alarm
ALARM_GPIO_PIN = 17

# Flow threshold in liters per minute
FLOW_THRESHOLD = 10.0


def configure_serial():
    """Opens and configures the serial port."""
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def configure_gpio():
    """Configures the GPIO pin for the flow alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_GPIO_PIN, GPIO.OUT)


def read_flow_rate(serial_port):
    """Reads a line from the serial port and returns the flow rate."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def trigger_alarm(flow_rate):
    """Activates or deactivates the alarm based on the flow rate."""
    if flow_rate is not None:
        if flow_rate > FLOW_THRESHOLD:
            GPIO.output(ALARM_GPIO_PIN, GPIO.HIGH)
            print("Flow alarm triggered!")
        else:
            GPIO.output(ALARM_GPIO_PIN, GPIO.LOW)


def main():
    """Main function to read flow data and control the alarm."""
    serial_connection = configure_serial()
    if serial_connection is None:
        return

    configure_gpio()

    try:
        while True:
            flow = read_flow_rate(serial_connection)
            if flow is not None:
                print(f"Flow rate: {flow} L/min")
                trigger_alarm(flow)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")


if __name__ == "__main__":
    main()

