import serial
import time
import pynmea2

# Configuration constants
UART_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None


def parse_gps_data(serial_port):
    """Reads and parses GPS data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace')
        if line.startswith('$GPGGA'):
            msg = pynmea2.parse(line)
            return msg
        return None
    except pynmea2.ParseError as e:
        print(f"NMEA Parse Error: {e}")
        return None
    except UnicodeDecodeError as e:
        print(f"Unicode Decode Error: {e}")
        return None


def log_coordinates(msg, log_filepath):
    """Logs the GPS coordinates to a file."""
    try:
        latitude = msg.latitude
        longitude = msg.longitude
        altitude = msg.altitude
        timestamp = msg.timestamp.strftime('%Y-%m-%dT%H:%M:%S')
        log_entry = f'{timestamp} - Latitude: {latitude} degrees, Longitude: {longitude} degrees, Altitude: {altitude} meters\n'
        with open(log_filepath, 'a') as log_file:
            log_file.write(log_entry)
        print(f'Logged: {log_entry.strip()}')
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main():
    """Main function to read, parse, and log GPS data."""
    serial_port = initialize_serial(UART_PORT, BAUD_RATE, TIMEOUT)
    if serial_port is None:
        return

    try:
        while True:
            gps_data = parse_gps_data(serial_port)
            if gps_data and hasattr(gps_data, 'fix_quality') and gps_data.fix_quality == 1:
                log_coordinates(gps_data, LOG_FILE)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

