#!/usr/bin/env python3
"""
Simple Web API for controlling a device via SCPI over serial on Raspberry Pi.
"""

import json
import time
from threading import Thread
from typing import Union, Dict, Any

import serial
from flask import Flask, Response, request, jsonify, abort

app = Flask(__name__)

# Serial port configuration (adjust as needed)
SERIAL_PORT = '/dev/ttyUSB0'
BAUDRATE = 9600
TIMEOUT = 1

# Global variable to hold the data
DATA: list = [{"id": 1, "name": "CHIPS", "done": False},
              {"id": 2, "name": "garden", "done": False}]

# Global serial port object
SERIAL_PORT_OBJ = None


def initialize_serial() -> None:
    """Initializes the serial port."""
    global SERIAL_PORT_OBJ
    try:
        SERIAL_PORT_OBJ = serial.Serial(SERIAL_PORT, BAUDRATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        raise


def send_scpi_command(command: str) -> Union[str, None]:
    """Sends an SCPI command to the device and returns the response."""
    global SERIAL_PORT_OBJ
    if SERIAL_PORT_OBJ is None:
        print("Serial port not initialized.")
        return None

    try:
        SERIAL_PORT_OBJ.write((command + '\n').encode())
        time.sleep(0.1)  # Allow time for the device to respond
        response = SERIAL_PORT_OBJ.read_all().decode()
        return response
    except serial.SerialException as e:
        print(f"Error communicating with the device: {e}")
        return None


@app.route('/version', methods=['GET'])
def get_device_version() -> Response:
    """Retrieves the device version information via SCPI."""
    response = send_scpi_command('*IDN?')
    if response:
        html_content = f"""<DOCTYPE html>
<html>
<head><title>Device Version</title></head>
<body>
<h1>Device Version Information</h1>
<p>{response.replace('\n', '<br>')}</p>
</body>
</html>"""
        return Response(html_content, mimetype='text/html')
    else:
        return Response("Error communicating with the device.", status=503, mimetype='text/plain')


@app.route('/getdata', methods=['GET'])
def get_all_data() -> jsonify:
    """Returns all data as JSON."""
    return jsonify(DATA)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_single_data(item_id: int) -> jsonify:
    """Returns a specific item as JSON."""
    item = next((item for item in DATA if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def post_new_item(item_id: int, name: str) -> jsonify:
    """Posts a new item to the data list."""
    new_id = DATA[-1]['id'] + 1 if DATA else 1
    new_item: Dict[str, Union[int, str, bool]] = {
        "id": new_id,
        "name": name,
        "done": False
    }
    DATA.append(new_item)
    return jsonify(DATA)


@app.route('/postjson', methods=['POST'])
def post_json_data() -> jsonify:
    """Posts JSON data to the data list."""
    try:
        if request.content_type == 'application/json':
            body = request.get_json()
        elif request.content_type == 'application/x-www-form-urlencoded':
            body = request.form.to_dict()
        else:
            body = request.get_data().decode('utf-8')
            try:
                body = json.loads(body)  # Attempt to parse as JSON
            except json.JSONDecodeError:
                return Response("Invalid JSON data", status=400, mimetype='text/plain')

        if not body:
            return Response("No data provided", status=400, mimetype='text/plain')

        new_id = DATA[-1]['id'] + 1 if DATA else 1
        new_item: Dict[str, Any] = {
            "id": new_id,
            "name": body.get('name', ''),  # Use .get() with default value
            "done": body.get('done', '').lower() in ('true', 'yes', '1')  # Convert to boolean
        }
        DATA.append(new_item)
        return jsonify(DATA), 201

    except Exception as e:
        print(f"Error processing request: {e}")
        return Response(f"Server error: {e}", status=500, mimetype='text/plain')


def run_flask_app() -> None:
    """Runs the Flask application."""
    app.run(debug=True, host='0.0.0.0')


if __name__ == '__main__':
    try:
        initialize_serial()
        flask_thread = Thread(target=run_flask_app)
        flask_thread.start()

        # Keep the main thread alive (you might want to implement a better shutdown mechanism)
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        if SERIAL_PORT_OBJ:
            SERIAL_PORT_OBJ.close()
        print("Serial port closed.")

